class AdditionalServicesDialogController{constructor($mdDialog,$http,toastrService,jobId,clientId,speedId){this._$mdDialog=$mdDialog;this._$http=$http;this._toastrService=toastrService;this._jobId=jobId;this._clientId=clientId;this._speedId=speedId;this.isLoading=false;this.additionalServices=[];this.totalServicesCount=0;this.getServices().then(serviceResponse=>{this.additionalServices=serviceResponse.items;this.totalServicesCount=serviceResponse.totalCount})}async getServices(){const url="job/GetAllClientItemsBySpeed";let response=await this._$http.get(url+"?clientId="+this._clientId+"&speedId="+this._speedId+"&jobId="+this._jobId);return response.data}getTotal(){return 1}async bookServices(allJobServices){try{const serviceIds=allJobServices.filter(service=>service.selected).map(service=>service.itemId);const url="job/AddClientItemsTobJob";await this._$http({method:"POST",url:url+"?jobId="+this._jobId,data:serviceIds});this._toastrService.showSuccessToast(serviceIds.length+" total services have been added to Job")}catch(error){this._toastrService.showErrorToast(error.message)}}cancel(){this._$mdDialog.cancel()}}